///////////////////////////////////////////////////////////////
// IMAGE (MAIN) SHADER - with spacebar toggle from Buffer C
///////////////////////////////////////////////////////////////
#define MAX_SITES 200

// Suppose ring A => IDs [0..13], ring B => IDs [14..27]
// So swirl => IDs [28..199]
#define RING_COUNT_SINGLE 14
#define RING_COUNT_DOUBLE (2 * RING_COUNT_SINGLE)
#define SWIRL_THRESHOLD   28

#define MAX_STEPS 120
#define MAX_DIST 50.0
#define CUBE_SIZE 1.0
#define MAX_SITES_PER_CELL 50

// step size
#define BASE_STEP 0.006

struct Site {
    vec3 pos;
    float weight;
};

// --------------------------------------------------
// iChannel0 => read site data + grid from Buffer A (or B)
Site getSite(int idx)
{
    vec4 data = texelFetch(iChannel0, ivec2(idx, 0), 0);
    Site s;
    s.pos    = data.xyz;
    s.weight = data.w;
    return s;
}

int getGridCount(int cIdx)
{
    float cF = texelFetch(iChannel0, ivec2(0, cIdx + 2), 0).r;
    return int(cF);
}

int getGridSite(int cIdx, int j)
{
    float sF = texelFetch(iChannel0, ivec2(j + 1, cIdx + 2), 0).r;
    return int(sF);
}

ivec3 posToGrid(vec3 p)
{
    vec3 gf = (p / CUBE_SIZE + 1.0) * 0.5 * 5.0;
    return clamp(ivec3(gf), ivec3(0), ivec3(4));
}

int gridIndex(ivec3 c)
{
    return c.x + 5 * (c.y + 5 * c.z);
}

// --------------------------------------------------
// Modified getCellInfo with skipSwirl
// If skipSwirl=true, we ignore swirl sites in the distance checks
void getCellInfo(
    vec3 p,
    out float d1, out int cellId,
    out float d2, out float d3,
    bool skipSwirl
){
    d1 = MAX_DIST;
    d2 = MAX_DIST;
    d3 = MAX_DIST;
    cellId = -1;

    ivec3 gp = posToGrid(p);
    int cIdx = gridIndex(gp);
    int cCount = getGridCount(cIdx);

    // Center cell
    for(int i=0; i<cCount; i++){
        int sId = getGridSite(cIdx, i);

        // *** skip swirl if requested ***
        if(skipSwirl && sId >= SWIRL_THRESHOLD) {
            continue;
        }

        float dist = length(p - getSite(sId).pos);
        // Insert into nearest distances
        if(dist < d1){
            d3 = d2;
            d2 = d1;
            d1 = dist;
            cellId = sId;
        }
        else if(dist < d2){
            d3 = d2;
            d2 = dist;
        }
        else if(dist < d3){
            d3 = dist;
        }
    }

    // Neighbors
    for(int dx=-1; dx<=1; dx++){
      for(int dy=-1; dy<=1; dy++){
        for(int dz=-1; dz<=1; dz++){
          if(dx==0 && dy==0 && dz==0) continue;
          ivec3 nb = gp + ivec3(dx,dy,dz);
          if(any(lessThan(nb, ivec3(0))) || any(greaterThanEqual(nb, ivec3(5))))
             continue;

          int nbIdx = gridIndex(nb);
          int nCount= getGridCount(nbIdx);
          for(int k=0; k<nCount; k++){
              int sId = getGridSite(nbIdx, k);

              // skip swirl if requested
              if(skipSwirl && sId >= SWIRL_THRESHOLD) {
                  continue;
              }

              float dist = length(p - getSite(sId).pos);
              if(dist < d1){
                  d3 = d2;
                  d2 = d1;
                  d1 = dist;
                  cellId = sId;
              }
              else if(dist < d2){
                  d3 = d2;
                  d2 = dist;
              }
              else if(dist < d3){
                  d3 = dist;
              }
          }
        }
      }
    }
}

// --------------------------------------------------
// Cube intersection [-1..1]
vec2 cubeIntersection(vec3 ro, vec3 rd)
{
    vec3 invDir = 1.0 / rd;
    vec3 t1 = (vec3(-1.0) - ro)*invDir;
    vec3 t2 = (vec3(+1.0) - ro)*invDir;
    vec3 tn = min(t1, t2);
    vec3 tf = max(t1, t2);

    float nearT = max(max(tn.x, tn.y), tn.z);
    float farT  = min(min(tf.x, tf.y), tf.z);

    return vec2(nearT, farT);
}

// --------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    //-----------------------------------------------------
    // 1) Camera
    //-----------------------------------------------------
    float yaw   = (iMouse.x / iResolution.x)*6.283185 - 3.14159;
    float pitch = 1.5708 - (iMouse.y / iResolution.y)*3.14159; // inverted pitch
    float sy= sin(pitch), cy= cos(pitch);
    float sx= sin(yaw),   cx= cos(yaw);
    float radius= 3.0;

    vec3 ro= vec3(
        radius * cy * sx,
        radius * sy,
        radius * cy * cx
    );
    vec3 lookAt= vec3(0.0);
    vec3 fwd= normalize(lookAt - ro);
    vec3 upTemp= vec3(0,1,0);
    vec3 right= normalize(cross(upTemp, fwd));
    vec3 up   = cross(fwd, right);

    vec2 uv= (fragCoord - 0.5*iResolution.xy)/ iResolution.y;
    vec3 rd= normalize(mat3(right, up, fwd)* vec3(uv, 1.0));

    //-----------------------------------------------------
    // 2) Background
    //-----------------------------------------------------
    vec3 bg= mix(vec3(0.3), vec3(0.01),
                 clamp(1.0 - (uv.y*0.5 + 0.5), 0.0,1.0));
    vec4 finalColor= vec4(bg,1.0);

    //-----------------------------------------------------
    // 3) Switch "hide swirl" via spacebar toggle in Buffer C
    //    (instead of the left mouse button)
    //-----------------------------------------------------
    float toggleState = texelFetch(iChannel2, ivec2(0,0), 0).r; 
    bool hideSwirl    = (toggleState > 0.5);

    //-----------------------------------------------------
    // 4) Raymarch bounding cube
    //-----------------------------------------------------
    vec2 tC= cubeIntersection(ro, rd);
    if(tC.x < tC.y && tC.y>0.0)
    {
        float t= max(tC.x, 0.0);
        float tEnd= tC.y;

        vec4 acc= vec4(0.0);
        for(int i=0; i<MAX_STEPS && t<tEnd; i++)
        {
            if(acc.a>0.99) break;

            vec3 pos= ro + rd*t;

            // read site data with possible swirl skip
            float d1, d2, d3;
            int cellId;
            getCellInfo(pos, d1, cellId, d2, d3, hideSwirl);

            // triple-edge detection
            float boundaryDist= abs(d2 - d1);
            float tripleThreshold= 0.005;
            float delta12= abs(d2 - d1);
            float delta13= abs(d3 - d1);
            bool isTriple= (delta12 < tripleThreshold && delta13 < tripleThreshold);

            float stepSize= BASE_STEP;
            if(isTriple) stepSize= 0.002;

            // (A) triple-edge shading
            if(isTriple)
            {
                float e= 1.0 - smoothstep(0.0, tripleThreshold, max(delta12,delta13));
                float glow= 0.4*exp(-40.0* max(delta12,delta13));
                float combined= e + glow;
                vec3 edgeCol= vec3(0.0);
                float alpha= (1.0 - acc.a)*0.4;
                acc.rgb += edgeCol* combined* alpha*1.5;
                acc.a   += alpha;
            }
            else
            {
                // (B) face-edge
                float faceT= 0.005;
                if(boundaryDist< faceT)
                {
                    float fI= 1.0 - smoothstep(0.0, faceT, boundaryDist);
                    vec3 faceCol= vec3(0.9);
                    float alpha= (1.0 - acc.a)*0.03* fI;
                    acc.rgb += faceCol* alpha;
                    acc.a   += alpha;
                }
            }

            // (C) color ring
            if(cellId >= 0 && cellId < RING_COUNT_SINGLE)
            {
                // ring A => magenta
                float alpha= (1.0-acc.a)*0.15;
                vec3 magenta= vec3(1.0,0.0,1.0);
                acc.rgb += magenta* alpha;
                acc.a   += alpha;
            }
            else if(cellId >= RING_COUNT_SINGLE && cellId < RING_COUNT_DOUBLE)
            {
                // ring B => blue
                float alpha= (1.0-acc.a)*0.15;
                vec3 blue= vec3(0.0,0.0,1.0);
                acc.rgb += blue*alpha;
                acc.a   += alpha;
            }
            // else swirl => but if hideSwirl is true, we never found swirl as nearest.

            t += stepSize;
        }

        if(acc.a>0.0)
        {
            finalColor= mix(finalColor, vec4(acc.rgb/acc.a, acc.a), acc.a);
        }
    }

    fragColor= finalColor;
}

///////////////////////////////////////////////////////////////
// BUFFER A (and BUFFER B) - "Double Ring + Swirl + Ping-Pong"
///////////////////////////////////////////////////////////////
#define MAX_SITES 200

// We'll do 14 sites in ring A, 14 in ring B => 28 ring sites total
#define RING_COUNT_SINGLE 14
#define RING_COUNT_DOUBLE (2 * RING_COUNT_SINGLE)

// The rest (indices [28..199]) are swirl
#define RING_RADIUS 0.3
#define FLIP_SPEED 0.3       // how fast the flip wave travels
#define SWIRL_AMP 0.10       // swirl amplitude
#define TIME_STEP 0.016
#define REPULSION_RADIUS 0.05
#define REPULSION_STRENGTH 0.2
#define DAMPING 0.98

// 5x5x5 => 125 cells
#define GRID_3D_SIZE 5
#define MAX_SITES_PER_CELL 50
#define CUBE_SIZE 1.0

//---------------------------------------------------------
// We'll store data as follows:
//   row=0 => positions (x,y,z,1)
//   row=1 => velocities (vx,vy,vz,1)
//   rows=2..126 => 125 grid rows
// Ping-pong: This buffer reads from iChannel0 = the OTHER buffer's prev frame
//---------------------------------------------------------

// Simple hash (for swirl init)
vec3 hash33(vec3 p3)
{
    p3 = fract(p3 * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yxz + 19.19);
    return -1.0 + 2.0 * fract((p3.xxy + p3.yzz) * p3.zyx);
}

// Map position [-1..1] => cell [0..5)
ivec3 calculateGridPos(vec3 pos)
{
    vec3 f = (pos / CUBE_SIZE + 1.0) * 0.5 * float(GRID_3D_SIZE);
    return clamp(ivec3(f), ivec3(0), ivec3(GRID_3D_SIZE-1));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 ip = ivec2(fragCoord);

    /////////////////////////////////////////////////////////////
    // 1) Rows 0..1 => position & velocity
    /////////////////////////////////////////////////////////////
    if(ip.y < 2 && ip.x < MAX_SITES)
    {
        int siteID = ip.x;
        int row    = ip.y;

        // First frame => initialize
        if(iFrame == 0)
        {
            if(row == 0)
            {
                // row=0 => position
                if(siteID < RING_COUNT_DOUBLE)
                {
                    // We have 28 ring sites => ring A=0..13, ring B=14..27
                    int i = siteID % RING_COUNT_SINGLE;   // 0..13
                    float fi = float(i);
                    float angle = fi * 6.283185307 / float(RING_COUNT_SINGLE);

                    // "A" ring is at angle
                    vec3 posA = vec3(
                        0.0,
                        RING_RADIUS * cos(angle),
                        RING_RADIUS * sin(angle)
                    );

                    // "B" ring offset by 180° => angle+π
                    vec3 posB = vec3(
                        0.0,
                        RING_RADIUS * cos(angle + 3.14159),
                        RING_RADIUS * sin(angle + 3.14159)
                    );

                    if(siteID < RING_COUNT_SINGLE)
                    {
                        // ring A
                        fragColor = vec4(posA, 1.0);
                    }
                    else
                    {
                        // ring B
                        fragColor = vec4(posB, 1.0);
                    }
                }
                else
                {
                    // swirl sites => [28..199]
                    float fi = float(siteID);
                    // random base in [-0.9..0.9]
                    vec3 base = hash33(vec3(fi*0.0573, fi*0.0731, fi*0.0917)) * 0.9;
                    fragColor = vec4(base, 1.0);
                }
            }
            else
            {
                // row=1 => velocity => zero
                fragColor = vec4(0.0, 0.0, 0.0, 1.0);
            }
            return;
        }
        else
        {
            // Subsequent frames => read old pos & vel from iChannel0
            vec4 oldPos4 = texelFetch(iChannel0, ivec2(siteID,0), 0);
            vec4 oldVel4 = texelFetch(iChannel0, ivec2(siteID,1), 0);
            vec3 pos = oldPos4.xyz;
            vec3 vel = oldVel4.xyz;

            if(row == 0)
            {
                //------------------------------------------------
                // row=0 => produce new final position
                //------------------------------------------------
                if(siteID < RING_COUNT_DOUBLE)
                {
                    // Double ring with traveling flip
                    int i = siteID % RING_COUNT_SINGLE;
                    float fi = float(i);
                    float angle = fi * 6.283185307 / float(RING_COUNT_SINGLE);

                    // ring A base
                    vec3 posA = vec3(
                        0.0,
                        RING_RADIUS * cos(angle),
                        RING_RADIUS * sin(angle)
                    );
                    // ring B base
                    vec3 posB = vec3(
                        0.0,
                        RING_RADIUS * cos(angle + 3.14159),
                        RING_RADIUS * sin(angle + 3.14159)
                    );

                    // traveling wave param => 0..1
                    float wave = fract( (angle - iTime*FLIP_SPEED)/(6.283185307) );
                    // small zone for flipping
                    float zone = 0.05;
                    float flipFactor = smoothstep(0.5 - zone, 0.5, wave)
                                     * (1.0 - smoothstep(0.5, 0.5 + zone, wave));

                    if(siteID < RING_COUNT_SINGLE)
                    {
                        // ring A => flip from A->B
                        pos = mix(posA, posB, flipFactor);
                    }
                    else
                    {
                        // ring B => flip from B->A
                        pos = mix(posB, posA, flipFactor);
                    }
                }
                else
                {
                    // swirl impetus
                    float fi = float(siteID);
                    float t  = iTime * 0.25;

                    // minimal swirl => add small sine offset
                    float swirlX = pos.x + SWIRL_AMP * sin(t + fi*0.3);
                    float swirlY = pos.y + SWIRL_AMP * sin(t*0.7 + fi*0.5);
                    float swirlZ = pos.z + 0.08     * sin(t*0.4 + fi*1.1);

                    // partial blend so it’s not jerky
                    pos.x = mix(pos.x, swirlX, 0.1);
                    pos.y = mix(pos.y, swirlY, 0.1);
                    pos.z = mix(pos.z, swirlZ, 0.1);
                }

                // Repulsion => naive O(N^2)
                vec3 force = vec3(0.0);
                for(int j=0; j<MAX_SITES; j++)
                {
                    if(j == siteID) continue;
                    vec3 oPos = texelFetch(iChannel0, ivec2(j,0), 0).xyz;
                    vec3 diff = pos - oPos;
                    float d   = length(diff);
                    if(d > 0.0 && d < REPULSION_RADIUS)
                    {
                        float overlap = (REPULSION_RADIUS - d);
                        vec3 dir      = diff / d;
                        force        += dir * overlap * REPULSION_STRENGTH;
                    }
                }
                vel += force * TIME_STEP;
                vel *= DAMPING;

                // final pos => pos + vel * dt
                pos += vel * TIME_STEP;

                // optional periodic boundary => re-enter from opposite side
                if(pos.x > 1.0)  pos.x -= 2.0;
                if(pos.x < -1.0) pos.x += 2.0;
                if(pos.y > 1.0)  pos.y -= 2.0;
                if(pos.y < -1.0) pos.y += 2.0;
                if(pos.z > 1.0)  pos.z -= 2.0;
                if(pos.z < -1.0) pos.z += 2.0;

                // store final
                fragColor = vec4(pos, 1.0);
            }
            else
            {
                // row=1 => produce new velocity
                // We basically keep or slightly damp oldVel
                vec3 newVel = vel * 0.99;
                fragColor = vec4(newVel, 1.0);
            }
            return;
        }
    }

    /////////////////////////////////////////////////////////////
    // 2) Build 5x5x5 grid => rows=2..126 => 125
    /////////////////////////////////////////////////////////////
    int grid_size = GRID_3D_SIZE*GRID_3D_SIZE*GRID_3D_SIZE; // 125
    if(ip.y >= 2 && ip.y < 2 + grid_size)
    {
        int row2 = ip.y - 2; // 0..124
        int gridIndex = row2;
        int sites_per_row = MAX_SITES_PER_CELL + 1;

        if(ip.x < 1)
        {
            // first pixel => how many sites in this cell
            int grid_count = 0;
            ivec3 cellPos = ivec3(
                (gridIndex % GRID_3D_SIZE),
                ((gridIndex / GRID_3D_SIZE) % GRID_3D_SIZE),
                (gridIndex / (GRID_3D_SIZE*GRID_3D_SIZE))
            );
            for(int i=0; i<MAX_SITES; i++)
            {
                vec3 sPos = texelFetch(iChannel0, ivec2(i, 0), 0).xyz;
                ivec3 c   = calculateGridPos(sPos);
                if(c == cellPos)
                    grid_count++;
            }
            fragColor = vec4(float(grid_count), 0.0, 0.0, 0.0);
        }
        else if(ip.x < sites_per_row)
        {
            // store site IDs
            int grid_count = 0;
            ivec3 cellPos = ivec3(
                (gridIndex % GRID_3D_SIZE),
                ((gridIndex / GRID_3D_SIZE) % GRID_3D_SIZE),
                (gridIndex / (GRID_3D_SIZE*GRID_3D_SIZE))
            );
            int outID = -1;
            for(int i=0; i<MAX_SITES; i++)
            {
                vec3 sPos = texelFetch(iChannel0, ivec2(i, 0), 0).xyz;
                ivec3 c   = calculateGridPos(sPos);
                if(c == cellPos)
                {
                    if(grid_count == ip.x - 1)
                        outID = i;
                    grid_count++;
                }
            }
            fragColor = vec4(float(outID)+0.5, 0.0, 0.0, 0.0);
        }
        else
        {
            fragColor = vec4(0.0);
        }
        return;
    }

    // pass-thru everything else
    fragColor = texelFetch(iChannel0, ip, 0);
}

